package com.kinto.trendyollab;
import java.net.URI;
import java.util.Locale;
public final class UrlPolicy {
 private static URI secure(String raw)throws Exception {URI u=new URI(raw);if(!"https".equalsIgnoreCase(u.getScheme())||u.getRawUserInfo()!=null||(u.getPort()!=-1&&u.getPort()!=443)||u.getHost()==null)throw new IllegalArgumentException();return u;}
 public static String source(String raw){try{String h=secure(raw).getHost().toLowerCase(Locale.ROOT);if(h.equals("trendyol.com")||h.endsWith(".trendyol.com"))return "trendyol";if(h.equals("hepsiburada.com")||h.equals("www.hepsiburada.com")||h.equals("m.hepsiburada.com"))return "hepsiburada";if(h.equals("zara.com")||h.equals("www.zara.com"))return "zara";if(h.equals("shop.mango.com"))return "mango";if(h.equals("madparfum.com")||h.equals("www.madparfum.com"))return "madparfum";if(h.equals("madamecoco.com")||h.equals("www.madamecoco.com"))return "madamecoco";}catch(Exception ignored){}return "";}
 public static boolean allowed(String raw){return !source(raw).isEmpty();}
 public static boolean product(String raw){try{String source=source(raw),path=secure(raw).getPath();return source.equals("mango")?path.matches("^/tr/tr/p/.+/[0-9]{8}/[0-9]{2}/[0-9]{2}/?$"):source.equals("madparfum")?path.matches("(?i)^/urun/[a-z0-9-]+/$"):source.equals("trendyol")?path.matches(".*-p-[0-9]+(?:/.*)?"):source.equals("zara")?path.matches("^/tr/tr/[^/]+-p[0-9]{8}\\.html$"):source.equals("madamecoco")?madameProduct(path):source.equals("hepsiburada")&&path.matches(".*-(?:p|pm)-[A-Za-z0-9]{3,40}/?");}catch(Exception e){return false;}}
 private static boolean madameProduct(String path){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i).*-([a-z0-9]{5,30})-[0-9]{1,5}/?").matcher(path);return m.matches()&&m.group(1).matches("(?i).*[a-z].*")&&m.group(1).matches(".*[0-9].*");}
 public static boolean image(String raw){try{String h=secure(raw).getHost().toLowerCase(Locale.ROOT);return (h.equals("media.mango.com")&&secure(raw).getPath().startsWith("/is/image/punto/"))||(h.equals("ba62e8.cdn.akinoncloud.com")&&secure(raw).getPath().startsWith("/products/"))||(h.equals("4d0873.akinoncloudcdn.com")&&secure(raw).getPath().startsWith("/products/"))||(h.equals("static.zara.net")&&secure(raw).getPath().startsWith("/assets/"))||h.equals("productimages.hepsiburada.net")||h.equals("dsmcdn.com")||h.endsWith(".dsmcdn.com")||h.equals("trendyolcdn.com")||h.endsWith(".trendyolcdn.com")||h.equals("trendyol.com")||h.endsWith(".trendyol.com");}catch(Exception e){return false;}}
}
